// Preferred — dependencies visible and swappable in tests
class UserRepository @Inject constructor(
    private val api: UserApi,
    private val dao: UserDao
)

// test: no DI framework needed at all
val repo = UserRepository(fakeApi, fakeDao)

@Module
@InstallIn(SingletonComponent::class)
abstract class DataModule {
    @Binds
    abstract fun bindUserRepository(impl: UserRepositoryImpl): UserRepository
}

@Module
@InstallIn(SingletonComponent::class)
object NetworkModule {
    @Provides
    @Singleton
    fun provideRetrofit(): Retrofit = Retrofit.Builder().baseUrl(BASE_URL).build()
}

@Singleton                       // one instance for the whole app
class AnalyticsTracker @Inject constructor()

@ViewModelScoped                 // one instance per ViewModel
class SearchHistory @Inject constructor()

class DateFormatter @Inject constructor() // unscoped: new instance each injection

@Module
@TestInstallIn(
    components = [SingletonComponent::class],
    replaces = [DataModule::class]
)
abstract class FakeDataModule {
    @Binds
    abstract fun bindUserRepository(fake: FakeUserRepository): UserRepository
}

@HiltAndroidTest
class ProfileScreenTest {
    @get:Rule val hiltRule = HiltAndroidRule(this)
}

// Koin: verify the module graph in a unit test (koin-test)
class ModulesTest {
    @Test
    fun verifyModules() {
        appModule.verify()   // fails if a definition's dependency isn't declared
    }
}
